const decorateInvoiceReminderButtons = () => { if (drawer.dataset.view !== 'invoices') return; recordList.querySelectorAll('.record-card').forEach((card) => { const id = card.querySelector('.record-id')?.textContent?.trim(); const status = card.querySelector('.record-status')?.textContent?.trim(); if (!/^INV-\d{13,}$/.test(id || '') || status === 'Paid' || card.querySelector('[data-invoice-reminder-action]')) return; const actions = card.querySelector('.record-actions') || (() => { const created = document.createElement('div'); created.className = 'record-actions'; card.querySelector('div')?.append(created); return created; })(); const button = document.createElement('button'); button.className = 'ghost-btn'; button.dataset.invoiceReminderAction = 'remind'; button.dataset.invoiceId = id; button.textContent = 'Send reminder'; actions.append(button); }); };
