const decorateEstimateReminderButtons = () => { if (drawer.dataset.view !== 'estimates') return; recordList.querySelectorAll('.record-card').forEach((card) => { const id = card.querySelector('.record-id')?.textContent?.trim(); const status = card.querySelector('.record-status')?.textContent?.trim(); if (!/^EST-\d{13,}$/.test(id || '') || status === 'Accepted' || card.querySelector('[data-estimate-reminder-action]')) return; const actions = card.querySelector('.record-actions') || (() => { const created = document.createElement('div'); created.className = 'record-actions'; card.querySelector('div')?.append(created); return created; })(); const button = document.createElement('button'); button.className = 'ghost-btn'; button.dataset.estimateReminderAction = 'remind'; button.dataset.estimateId = id; button.textContent = 'Send follow-up'; actions.append(button); }); };
