const decorateAppointmentReminderButtons = () => { if (drawer.dataset.view !== 'dispatch') return; recordList.querySelectorAll('.dispatch-job .record-actions').forEach((actions) => { const job = actions.closest('[data-dispatch-job]'); const status = job?.querySelector('.dispatch-job-meta span')?.textContent; if (!job || ['Completed', 'Canceled'].includes(status) || actions.querySelector('[data-appointment-reminder-action]')) return; const button = document.createElement('button'); button.className = 'ghost-btn'; button.dataset.appointmentReminderAction = 'remind'; button.dataset.jobId = job.dataset.dispatchJob; button.textContent = 'Send reminder'; actions.append(button); }); };
