const decorateJobVisitButtons = () => { if (drawer.dataset.view !== 'dispatch') return; recordList.querySelectorAll('.dispatch-job .record-actions').forEach((actions) => { const job = actions.closest('[data-dispatch-job]'); if (!job || actions.querySelector('[data-job-visit-action]')) return; const addButton = document.createElement('button'); addButton.className = 'ghost-btn'; addButton.dataset.jobVisitAction = 'add'; addButton.dataset.jobId = job.dataset.dispatchJob; addButton.textContent = 'Add visit'; actions.append(addButton); const statusButton = document.createElement('button'); statusButton.className = 'ghost-btn'; statusButton.dataset.jobVisitAction = 'status'; statusButton.dataset.jobId = job.dataset.dispatchJob; statusButton.textContent = 'Visit status'; actions.append(statusButton); }); };
const jobVisitObserver = new MutationObserver(decorateJobVisitButtons);
jobVisitObserver.observe(recordList, { childList: true, subtree: true });
recordList.addEventListener('click', async (event) => { const button = event.target.closest('[data-job-visit-action]'); if (!button) return; button.disabled = true; try { if (button.dataset.jobVisitAction === 'add') { const time = window.prompt('Visit schedule time', 'Next day 9:00 AM'); if (!time) return; const technician = window.prompt('Technician (optional)', ''); await repository.addJobVisit(button.dataset.jobId, time, technician || ''); showToast('Work-order visit added.'); openRecords('dispatch'); } else { const result = await repository.listJobVisits(button.dataset.jobId); if (!result.visits.length) { showToast('No visits are scheduled yet.'); return; } const selected = Number(window.prompt(`Visit number (1-${result.visits.length})`, '1')); const visit = result.visits[selected - 1]; if (!visit) return; const nextStatus = window.prompt('Status: En route, In progress, Completed, or Canceled', visit.status === 'Scheduled' ? 'En route' : 'Completed'); if (!['En route', 'In progress', 'Completed', 'Canceled'].includes(nextStatus)) return; await repository.updateJobVisitStatus(button.dataset.jobId, visit.id, nextStatus); showToast(`Visit ${visit.sequence} marked ${nextStatus}.`); } } catch { showToast('Could not update work-order visit.'); } finally { button.disabled = false; } });
